p = argparse.ArgumentParser(prog="xan " + command)
p.add_argument("-n", "--no-headers", action="store_true")
p.add_argument("-d", "--delimiter", default=",")
p.add_argument("-o", "--output")
if command == "explode":
    p.add_argument("--sep", default="|")
    p.add_argument("-S", "--singularize", action="store_true")
    p.add_argument("-r", "--rename")
    p.add_argument("-D", "--drop-empty", action="store_true")
elif command == "implode":
    p.add_argument("--sep", default="|")
    p.add_argument("-P", "--pluralize", action="store_true")
    p.add_argument("-r", "--rename")
    p.add_argument("--cmp")
else:
    p.add_argument("-r", "--regex", action="store_true")
    p.add_argument("-m", "--match", action="store_true")
    p.add_argument("-c", "--captures", action="store_true")
    p.add_argument("-C", "--all-captures", action="store_true")
    p.add_argument("-M", "--max", type=int)
    p.add_argument("--into")
    p.add_argument("--prefix")
    p.add_argument("-k", "--keep", action="store_true")
    p.add_argument("--trim", action="store_true")
    p.add_argument("--fixed-width", action="store_true")
p.add_argument("column")
if command == "separate":
    p.add_argument("separator")
else:
    p.add_argument("columns")
p.add_argument("input", nargs="?")
ns = p.parse_intermixed_args(args)
if len(ns.delimiter) != 1:
    p.error("delimiter must be a single character")
source = open(ns.input, newline="", encoding="utf-8") if ns.input and ns.input != "-" else sys.stdin
try:
    table = list(csv.reader(source, delimiter=ns.delimiter))
finally:
    if source is not sys.stdin:
        source.close()
if ns.no_headers:
    width = max(map(len, table), default=0)
    headers = [str(i) for i in range(width)]
    rows = table
else:
    headers = table[0] if table else []
    rows = table[1:] if table else []
def resolve(expr):
    result = []
    for part in expr.split(","):
        part = part.strip()
        if part in headers:
            idx = headers.index(part)
        else:
            try:
                idx = int(part)
            except ValueError:
                raise ValueError("column not found: " + part)
        if idx < 0 or idx >= len(headers):
            raise ValueError("column index out of range: " + part)
        if idx not in result:
            result.append(idx)
    return result
try:
    indices = resolve(ns.columns)
    names = None
    if ns.rename is not None:
        names = next(csv.reader([ns.rename]))
if command == "separate":
    try:
        idx = resolve(ns.column)
        if len(idx) != 1:
            raise ValueError("separate expects one column")
        idx = idx[0]
        extracted = []
        max_parts = ns.max
        import re
        for row in rows:
            value = row[idx]
            if ns.captures or ns.all_captures:
                pattern = re.compile(ns.separator)
                matches = list(pattern.finditer(value))
                chunks = [m.groups() for m in matches]
                if ns.captures:
                    m = pattern.search(value)
                    chunks = [m.groups() if m else ()]
                parts = [v for match in chunks for v in match]
            elif ns.match:
                parts = re.findall(ns.separator, value)
            elif ns.fixed_width:
                size = max(1, int(ns.separator))
                parts = [value[i:i+size] for i in range(0, len(value), size)]
            elif ns.regex:
                parts = re.split(ns.separator, value, maxsplit=max(0, ns.max-1) if ns.max else 0)
            else:
                parts = value.split(ns.separator, max(0, ns.max-1) if ns.max else -1)
            if ns.trim:
                parts = [v.strip() for v in parts]
            if max_parts is None:
                max_parts = len(parts)
            if len(parts) > max_parts:
                raise ValueError(f"Number of splits exceeded expected maximum {max_parts} but got {len(parts)}. Consider using the --too-many flag to handle extra splitted cells")
            extracted.append(parts)
        if ns.into:
            names = next(csv.reader([ns.into]))
        else:
            prefix = ns.prefix or ns.column
            names = [f"{prefix}{i+1}" for i in range(max_parts or 0)]
        if len(names) > (max_parts or len(names)):
            raise ValueError("number of names exceeds the maximum number of splits")
        if max_parts is None:
            max_parts = max((len(v) for v in extracted), default=0)
            if not ns.into:
                names = [f"{ns.prefix or ns.column}{i+1}" for i in range(max_parts)]
        names += [f"{(ns.prefix or ns.column)}{i+1}" for i in range(len(names), max_parts)]
        out_headers = headers[:idx] + (headers[idx:idx+1] if ns.keep else []) + names + headers[idx+1:]
        out_rows = []
        for row, parts in zip(rows, extracted):
            values = (row[idx:idx+1] if ns.keep else []) + parts + [""] * (max_parts-len(parts))
            out_rows.append(row[:idx] + values + row[idx+1:])
    except (ValueError, re.error) as exc:
        print(f"xan separate: {exc}.", file=sys.stderr)
        raise SystemExit(1)
elif command == "explode":
        out_headers, out_rows = explode(headers, rows, indices, ns.sep, names,
                                        ns.singularize, ns.drop_empty)
elif command == "implode":
        cmp_indices = resolve(ns.cmp) if ns.cmp else None
        out_headers, out_rows = implode(headers, rows, indices, ns.sep,
                                        names[0] if names else None,
                                        ns.pluralize, cmp_indices)
except ValueError as exc:
    print(f"xan {command}: {exc}.", file=sys.stderr)
    raise SystemExit(1)
dest = open(ns.output, "w", newline="", encoding="utf-8") if ns.output else sys.stdout
try:
    writer = csv.writer(dest, delimiter=ns.delimiter, lineterminator="\n")
    if not ns.no_headers:
        writer.writerow(out_headers)
    writer.writerows(out_rows)
finally:
    if dest is not sys.stdout:
        dest.close()

