#!/usr/bin/env python3
import sys,csv,argparse,re,os
import fillblank
import ops_sort
import tokenize_cmd
import histcmd
import basiccmd
import combine

def read_csv(path, delim):
    f=open(path,encoding='utf-8',newline='') if path and path!='-' else sys.stdin
    return f, list(csv.reader(f,delimiter=delim))

def write(rows, delim=','):
    w=csv.writer(sys.stdout,delimiter=delim,lineterminator='\n')
    w.writerows(rows)

def split_selection(s):
    try:return [x.strip() for x in next(csv.reader([s],skipinitialspace=True)) if x.strip()]
    except:return [x.strip().strip('"') for x in s.split(',') if x.strip()]

def col_index(token, header, n):
    if token.lstrip('-').isdigit():
        i=int(token); i=i if i>=0 else n+i
        if 0<=i<n:return i
    if token in header:
        return header.index(token)
    m=re.fullmatch(r'(.+)\[(-?\d+)\]',token)
    if m:
        inds=[i for i,x in enumerate(header) if x==m.group(1)]
        j=int(m.group(2)); j=j if j>=0 else len(inds)+j
        if 0<=j<len(inds):return inds[j]
    raise ValueError('Unknown column: '+token)

def selection(s, header, n):
    out=[]
    for tok in split_selection(s):
        if tok=='*': out.extend(range(n)); continue
        if '*' in tok:
            if tok.startswith('*'): out.extend(i for i,x in enumerate(header) if x.endswith(tok[1:]))
            elif tok.endswith('*'): out.extend(i for i,x in enumerate(header) if x.startswith(tok[:-1]))
            continue
        if ':' in tok:
            a,b=tok.split(':',1)
            lo=col_index(a,header,n) if a else 0
            hi=col_index(b,header,n) if b else n-1
            step=1 if hi>=lo else -1
            out.extend(range(lo,hi+step,step));continue
        out.append(col_index(tok,header,n))
    return out

def main():
    args=sys.argv[1:]
    if not args or args[0] in ('-h','--help'):
        print('Usage: xan [options] <command> [<args>...]');return
    if args[0]=='--version': print('0.57.1');return
    delim=','; nohead=False; output=None
    i=0
    while i<len(args) and args[i] in ('-n','--no-headers','-d','--delimiter','-o','--output'):
        a=args[i]
        if a in ('-n','--no-headers'): nohead=True;i+=1
        else:
            if i+1>=len(args): raise ValueError('missing value for '+a)
            if a in ('-d','--delimiter'):delim=args[i+1]
            else:output=args[i+1]
            i+=2
    cmd=args[i]; rest=args[i+1:]
    if cmd == 'tokenize':
        return tokenize_cmd.run(rest)
    if cmd in ('cat','join'):
        cargs=(['-n'] if nohead else []) + (['-d',delim] if delim != ',' else []) + (['-o',output] if output else []) + rest
        return combine.cat(cargs) if cmd=='cat' else combine.join(cargs)
    if cmd in ('count','headers','h'):
        path=next((x for x in rest if not x.startswith('-')),None)
        if '-n' in rest or '--no-headers' in rest: nohead=True
        d=delim
        if '-d' in rest:
            try:d=rest[rest.index('-d')+1]
            except:pass
        f,rows=read_csv(path,d)
        if f is not sys.stdin:f.close()
        if cmd=='count': result=str(len(rows) if nohead else max(0,len(rows)-1))+'\n'
        else:
            h=rows if nohead else (rows[:1] if rows else [])
            names=h[0] if h else []
            result=''.join((x+'\n' if '-j' in rest or '--just-names' in rest else f'{i}   {x}\n') for i,x in enumerate(names))
        if output:
            with open(output,'w') as of:of.write(result)
        else:sys.stdout.write(result)
        return
    if cmd in ('explode','implode','separate'):
        from reshape_extra import cli as reshape_cli
        reshape_cli(cmd, (['-n'] if nohead else []) + (['-d',delim] if delim != ',' else []) + (['-o',output] if output else []) + rest)
        return
    if cmd in ('transpose','t'):
        f,rows=read_csv(next((x for x in rest if not x.startswith('-')),None),delim)
        if f is not sys.stdin:f.close()
        out=[list(x) for x in zip(*rows)] if rows else []
        if output:
            with open(output,'w',encoding='utf-8',newline='') as of:csv.writer(of,delimiter=delim,lineterminator='\n').writerows(out)
        else:write(out,delim)
        return
    if cmd in ('fill','blank'):
        fillblank.run(cmd, args[:i] + rest)
        return
    if cmd in ('count','headers','head','tail','reverse'):
        basiccmd.run(cmd, (['-n'] if nohead else []) + (['-d',delim] if delim != ',' else []) + (['-o',output] if output else []) + rest)
        return
    if cmd in ('sample','shuffle'):
        from sample_shuffle import run
        run(cmd, (['-n'] if nohead else []) + (['-d',delim] if delim != ',' else []) + (['-o',output] if output else []) + rest)
        return
    if cmd=='bisect':
        import bisectcmd
        bisectcmd.bisect((['-n'] if nohead else []) + (['-d',delim] if delim != ',' else []) + (['-o',output] if output else []) + rest)
        return
    if cmd in ('sort','range'):
        return ops_sort.run(cmd, (['-n'] if nohead else []) + (['-d',delim] if delim != ',' else []) + (['-o',output] if output else []) + rest)
    if cmd == 'hist':
        return histcmd.hist((['-n'] if nohead else []) + (['-d',delim] if delim != ',' else []) + (['-o',output] if output else []) + rest)
"}

